import json
import os
import sys
import re
import math
from datetime import datetime
from pathlib import Path

def parse_expr(expr):
    try:
        return eval(expr, {'__builtins__': None}, {})
    except:
        return None

def evaluate_placeholders(template):
    cache = {}
    vars_cache_path = "vars.cache"

    # Check cache
    vars_json_path = sys.argv[2]
    vars_json_mod_time = os.path.getmtime(vars_json_path)
    cache_exists = os.path.exists(vars_cache_path)
    cache_mod_time = os.path.getmtime(vars_cache_path) if cache_exists else 0

    if cache_exists and cache_mod_time >= vars_json_mod_time:
        try:
            with open(vars_cache_path, 'r') as f:
                cache = json.load(f)
            print("cache hit", file=sys.stderr)
        except Exception as e:
            print(f"error: {str(e)}", file=sys.stderr)
            sys.exit(1)
    else:
        try:
            with open(vars_json_path, 'r') as f:
                vars_json = json.load(f)
            for key, value in vars_json.items():
                cache[key] = value
            with open(vars_cache_path, 'w') as f:
                json.dump(vars_json, f)
            print("cache miss", file=sys.stderr)
        except Exception as e:
            print(f"error: {str(e)}", file=sys.stderr)
            sys.exit(1)

    def replace_placeholders(obj):
        if isinstance(obj, str):
            def replacer(match):
                expr = match.group(1)
                try:
                    value = parse_expr(expr)
                    if value is None:
                        return match.group(0)
                    print(f"placeholder: {match.group(0)} = {value}", file=sys.stderr)
                    return str(value)
                except Exception as e:
                    print(f"error: {str(e)}", file=sys.stderr)
                    sys.exit(1)
            return re.sub(r'\{\{([^}]+)\}\}', replacer, obj)
        elif isinstance(obj, dict):
            return {k: replace_placeholders(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_placeholders(v) for v in obj]
        return obj

    try:
        return replace_placeholders(template)
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 3:
        print("error: incorrect number of arguments", file=sys.stderr)
        sys.exit(1)

    template_path = sys.argv[1]
    vars_path = sys.argv[2]

    try:
        with open(template_path, 'r') as f:
            template = json.load(f)
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    rendered = evaluate_placeholders(template)
    print(json.dumps(rendered))

if __name__ == "__main__":
