import json
import sys
import re
import operator
from collections import OrderedDict

def evaluate_expr(expr, vars):
    try:
        # Replace variables with their values
        for var, val in vars.items():
            expr = expr.replace(var, str(val))
        # Define operator precedence and functions
        ops = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '//': operator.floordiv,
            '%': operator.mod,
            '**': operator.pow
        }
        # Use eval with restricted globals and locals
        return eval(expr, {'__builtins__': None}, {'__builtins__': None, 'ops': ops})
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

def replace_placeholders(template, vars):
    def process_value(value):
        if isinstance(value, str):
            return re.sub(r'\{\{([^}]+)\}\}', lambda m: str(evaluate_expr(m.group(1), vars)), value)
        elif isinstance(value, (list, tuple)):
            return [process_value(item) for item in value]
        elif isinstance(value, dict):
            return {k: process_value(v) for k, v in value.items()}
        else:
            return value

    try:
        result = process_value(template)
        return result
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 3:
        print("error: incorrect number of arguments", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[1], 'r') as f:
            template = json.load(f)
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[2], 'r') as f:
            vars = json.load(f)
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    processed = replace_placeholders(template, vars)

    try:
        print(json.dumps(processed, separators=(',', ':')))
    except Exception as e:
        print(f"error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

